import{_ as s,o as t,c as a,a3 as n}from"./chunks/framework.BlfGB29P.js";const i="/images/logic-studio/user-guide/blocks-a-fr.png",m=JSON.parse('{"title":"Blocks A","description":"","frontmatter":{},"headers":[],"relativePath":"fr/projects/logic-studio/user-guide/blocks-a.md","filePath":"fr/projects/logic-studio/user-guide/blocks-a.md","lastUpdated":1795870835000}'),r={name:"fr/projects/logic-studio/user-guide/blocks-a.md"};function o(l,e,c,u,d,p){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="blocks-a" tabindex="-1">Blocks A <a class="header-anchor" href="#blocks-a" aria-label="Permalink to &quot;Blocks A&quot;">​</a></h1><p><strong>Surface de travail depuis 0.1.137 :</strong> Grille de points sans alignement imposé. La molette déplace la vue ; Maj + molette la déplace horizontalement. Ctrl + molette change le zoom. Boutons de zoom et pincement également disponibles. Positions enregistrées des blocs conservées.</p><p><strong>Portée de 0.1.136 :</strong> le nouveau déclencheur d’état et l’ordre automatique avec confirmation concernent <strong>Blocks JS</strong>. Le YAML de Blocks A conserve son pont d’événements natif. Les deux variantes de capteur restent disponibles ; autorisations et projets enregistrés conservés. La validation sans Entrée et <strong>Vider le journal</strong> appartiennent à l’interface commune du Studio. 99 tests locaux réussis ; Test réel supplémentaire le 28 novembre 2026 après sauvegarde complète sur HA 2026.11.3 (.193, port 80) : branches d’état/d’attribut de Blocks JS, écriture avant débogage, saisie décimale sans Entrée, avertissement d’ancien code et effacement du journal. Valeurs de test restaurées, projets et autorisations conservés ; exemples arrêtés. <a href="./../#zustandstrigger-reihenfolge">Résultats du test réel</a>.</p><p><strong>0.1.135 :</strong> Les 51 champs d’entités directs des 285 blocs enregistrés dans Blocks A/JS ont été vérifiés pour la sélection HA. Le nouveau sélecteur multiple et les déclencheurs compacts concernent Blocks JS. Les champs de cibles HA structurés, les listes et les associations enregistrées dans Blocks A sont conservés. 68 tests Node et 12 tests serveur réussis ; aucun test réel sur HA pour cette version.</p><h2 id="sensorzustand-setzen" tabindex="-1">Définir l’état du capteur <a class="header-anchor" href="#sensorzustand-setzen" aria-label="Permalink to &quot;Définir l’état du capteur {#sensorzustand-setzen}&quot;">​</a></h2><h3 id="sensor-dezimalzahl" tabindex="-1">Saisir directement un nombre décimal <a class="header-anchor" href="#sensor-dezimalzahl" aria-label="Permalink to &quot;Saisir directement un nombre décimal {#sensor-dezimalzahl}&quot;">​</a></h3><p>Depuis <strong>0.1.134</strong> : choisir <strong>System → Définir l’état du capteur · Nombre décimal</strong>, sélectionner un capteur et saisir directement la valeur. Valeur par défaut <code>0.5</code> ; saisir par exemple <code>33.25</code> avec un point décimal. Aucun arrondi à un entier ; les valeurs restent enregistrées après rechargement. Le bloc avec entrée de valeur reste disponible. Autorisation WRITE et attributs traités de la même façon. Blocks A nécessite l’application Studio active.</p><p><strong>Vérifié :</strong> 72 tests locaux et, après sauvegarde sur HA 2026.11.3, <code>0.5</code> et <code>33.25</code> via Play dans Blocks JS et via les données d’événement générées et vérifiées de Blocks A. Les deux champs ont été confirmés après rechargement ; réglages et attributs conservés.</p><p>À partir de <strong>0.1.133</strong>, <strong>System</strong> propose <strong>Définir l’état du capteur</strong> :</p><ol><li>Sélectionne un <code>sensor.*</code> existant avec le sélecteur d’entités de style HA.</li><li>Connecte un nombre, un texte ou un calcul à l’entrée de valeur (état de 255 caractères maximum).</li><li>Autorise le capteur dans <strong>WRITE – cibles individuelles</strong> (<code>runtime_write_entities</code>) dans la configuration de l’application. Conserve les entrées existantes. READ seul ne suffit pas.</li><li>Choisis <strong>Vérifier les blocs → Ouvrir en YAML HA</strong>. Vérifie puis installe toi-même l’automatisation dans Home Assistant.</li></ol><p>Exemple d’action générée :</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">event</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">logic_studio_set_sensor_state</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    event_data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      entity_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sensor.example</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      state</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">43</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>L’application Studio active reçoit l’événement et vérifie WRITE. Sans l’application, il n’est pas traité. Cette entrée interne ne nécessite pas d’autorisation EVENT générale. Les erreurs apparaissent dans le journal de l’application ; émettre l’événement ne confirme pas la réussite de l’écriture.</p><p>Le bloc conserve l’unité, la classe d’appareil et les autres attributs. Il correspond à <strong>Outils de développement → États</strong>, ne commande aucun appareil et ne crée aucun capteur permanent. L’intégration responsable peut remplacer la valeur ultérieurement. L’aperçu YAML n’écrit rien.</p><h2 id="premier-exemple" tabindex="-1">Premier exemple <a class="header-anchor" href="#premier-exemple" aria-label="Permalink to &quot;Premier exemple&quot;">​</a></h2><p>L’automatisation allume la lumière du couloir lorsque le capteur de mouvement passe à <code>on</code>.</p><ol><li>Choisis <strong>Nouveau projet → Blocks A</strong> et donne un nom au projet. Le bloc <strong>Automatisation</strong> apparaît sur le canevas.</li><li>Ouvre <strong>Déclencheurs</strong> et glisse un déclencheur d’état dans <strong>Quand</strong>. La capture utilise <code>binary_sensor.flur_bewegung</code> et l’état <code>on</code>. Choisis ton propre capteur ou une entrée de test.</li><li>Ouvre <strong>Actions</strong> et place une action dans <strong>Alors</strong>. La capture utilise <code>light.flur</code> et <strong>allumer</strong>. Tu peux choisir une deuxième entrée de test comme cible. Laisse <strong>Seulement si</strong> vide pour cet exemple.</li><li>Clique sur le drapeau pour vérifier les blocs. Si la vérification réussit, choisis <strong>Ouvrir en YAML HA</strong> et contrôle <code>triggers</code> et <code>actions</code> avant d’exporter.</li></ol><p><a href="/images/logic-studio/user-guide/blocks-a-fr.png"><img src="`+i+'" alt="Blocks A avec un déclencheur dans Quand et une action dans Alors"></a></p><h2 id="fonctions" tabindex="-1">Fonctions <a class="header-anchor" href="#fonctions" aria-label="Permalink to &quot;Fonctions&quot;">​</a></h2><h3 id="palette-et-connexions" tabindex="-1">Palette et connexions <a class="header-anchor" href="#palette-et-connexions" aria-label="Permalink to &quot;Palette et connexions&quot;">​</a></h3><p>Choisis un bloc selon son rôle. La forme des connexions indique où placer une valeur ou une action.</p><h3 id="declencheurs-et-conditions" tabindex="-1">Déclencheurs et conditions <a class="header-anchor" href="#declencheurs-et-conditions" aria-label="Permalink to &quot;Déclencheurs et conditions&quot;">​</a></h3><p>Un déclencheur démarre l’automatisation. Une condition peut vérifier si l’autre entrée est désactivée.</p><h3 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h3><p>Empile les actions dans leur ordre d’exécution.</p><h3 id="selecteurs-ha" tabindex="-1">Sélecteurs HA <a class="header-anchor" href="#selecteurs-ha" aria-label="Permalink to &quot;Sélecteurs HA&quot;">​</a></h3><p>Choisis une entité, une action, un appareil, une zone, une étiquette ou un étage. Vérifie l’identifiant correspondant dans le YAML.</p><h3 id="brouillon-ha-yaml" tabindex="-1">Brouillon HA-YAML <a class="header-anchor" href="#brouillon-ha-yaml" aria-label="Permalink to &quot;Brouillon HA-YAML&quot;">​</a></h3><p>Ouvre l’automatisation générée en brouillon. Le nom de son projet source y est affiché.</p><h3 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h3><p>Vérifie le YAML et utilise-le dans HA. Teste le déclencheur et consulte la trace de l’automatisation.</p><h2 id="en-cas-de-probleme" tabindex="-1">En cas de problème <a class="header-anchor" href="#en-cas-de-probleme" aria-label="Permalink to &quot;En cas de problème&quot;">​</a></h2><p>Si une liste est vide, vérifie que le système HA connecté contient les éléments recherchés.</p>',33)])])}const g=s(r,[["render",o]]);export{m as __pageData,g as default};
